using UnityEngine;
namespace Alterverse.Visuals
{
public sealed class RealityCoreShell:MonoBehaviour
{
Transform root;Material metal,secondary,energy;
public void Build(bool zero){root=new GameObject("DF_RealityCoreProduction").transform;root.SetParent(transform,false);root.localScale=Vector3.one*.72f;Color e=zero?StylizedArtDirection.ZeroEnergy:StylizedArtDirection.LumenEnergy;metal=Mat(Color.Lerp(StylizedArtDirection.Ink,zero?StylizedArtDirection.ZeroDark:StylizedArtDirection.LumenDark,.55f),.72f,.28f);secondary=Mat(Color.Lerp(Color.gray,zero?StylizedArtDirection.ZeroMid:StylizedArtDirection.LumenMid,.35f),.58f,.42f);energy=Mat(e,.15f,.65f,true);BuildBase();BuildFrame(zero);BuildChronosphere(zero);}
void BuildBase(){Disc("CoreLowerHousing",1.72f,.22f,.28f,metal);Disc("CoreUpperHousing",1.34f,.42f,.14f,secondary);for(int i=0;i<6;i++){float a=i*Mathf.PI/3f;Vector3 from=new(Mathf.Cos(a)*1.05f,.5f,Mathf.Sin(a)*1.05f),to=new(Mathf.Cos(a)*1.62f,.28f,Mathf.Sin(a)*1.62f);Tube("PowerFeed",from,to,.065f,i%2==0?energy:secondary);}}
void BuildFrame(bool zero){for(int i=0;i<4;i++){float a=(i*90+45)*Mathf.Deg2Rad;Vector3 foot=new(Mathf.Cos(a)*1.18f,.48f,Mathf.Sin(a)*1.18f);Vector3 shoulder=new(Mathf.Cos(a)*.78f,1.65f,Mathf.Sin(a)*.78f);Tube("ChronoStrut",foot,shoulder,.105f,metal);Vector3 brace=new(Mathf.Cos(a)*.96f,1.18f,Mathf.Sin(a)*.96f);Tube("EnergyConduit",foot+Vector3.up*.08f,brace,.035f,energy);Node(shoulder,.15f,secondary);}}
void BuildChronosphere(bool zero){Vector3 center=new(0,1.72f,0);Node(center,.34f,energy);float[] radii={.72f,.96f,1.18f};Vector3[] rotations={new(68,0,0),new(18,34,58),new(42,72,18)};for(int i=0;i<3;i++){GameObject ring=ProductionMeshFactory.MeshObject("DF_ChronoRing_"+i,root,ProductionMeshFactory.Ring(radii[i],.045f,i==2?32:28,8),i==1?secondary:metal);ring.transform.localPosition=center;ring.transform.localRotation=Quaternion.Euler(rotations[i]);var motion=ring.AddComponent<ChronoRingMotion>();motion.Configure((i%2==0?1:-1)*(12f+i*7f));for(int j=0;j<4;j++){float a=j*Mathf.PI*.5f;Vector3 p=center+new Vector3(Mathf.Cos(a)*radii[i],0,Mathf.Sin(a)*radii[i]);Node(p,.055f,energy);}}for(int i=0;i<3;i++){float a=(i*120+(zero?18:0))*Mathf.Deg2Rad;Vector3 p=center+new Vector3(Mathf.Cos(a)*1.38f,.12f*Mathf.Sin(a*2),Mathf.Sin(a)*1.38f);Node(p,.11f,secondary);Tube("FieldArm",new Vector3(Mathf.Cos(a)*.8f,1.62f,Mathf.Sin(a)*.8f),p,.045f,secondary);}}
void Disc(string n,float radius,float y,float height,Material mat){GameObject g=GameObject.CreatePrimitive(PrimitiveType.Cylinder);g.name="DF_"+n;g.transform.SetParent(root,false);g.transform.localPosition=new Vector3(0,y,0);g.transform.localScale=new Vector3(radius,height,radius);Destroy(g.GetComponent<Collider>());g.GetComponent<Renderer>().sharedMaterial=mat;}
void Tube(string n,Vector3 a,Vector3 b,float r,Material mat){ProductionMeshFactory.MeshObject("DF_"+n,root,ProductionMeshFactory.Tube(a,b,r,8),mat);}
void Node(Vector3 p,float r,Material mat){GameObject g=GameObject.CreatePrimitive(PrimitiveType.Sphere);g.name="DF_CoreNode";g.transform.SetParent(root,false);g.transform.localPosition=p;g.transform.localScale=Vector3.one*r;Destroy(g.GetComponent<Collider>());g.GetComponent<Renderer>().sharedMaterial=mat;}
Material Mat(Color c,float metallic,float smooth,bool emissive=false){Shader sh=Shader.Find("Universal Render Pipeline/Lit")??Shader.Find("Standard");Material m=new(sh);if(m.HasProperty("_BaseColor"))m.SetColor("_BaseColor",c);m.color=c;if(m.HasProperty("_Metallic"))m.SetFloat("_Metallic",metallic);if(m.HasProperty("_Smoothness"))m.SetFloat("_Smoothness",smooth);if(emissive){m.EnableKeyword("_EMISSION");m.SetColor("_EmissionColor",c*1.45f);}return m;}
}
}